import requests

def generate_qr_code(wallet_address, output_file):
    """
    Generates a QR code for a given Dogecoin wallet address using the qrcode-free.com API.

    Args:
        wallet_address (str): The Dogecoin wallet address to encode in the QR code.
        output_file (str): The file path to save the generated QR code image.

    Returns:
        None
    """
    # Base URL for the QR code generation API
    api_url = "https://api.qrcode-free.com"

    # Parameters for the API request
    params = {
        "data": wallet_address,  # The data to encode in the QR code
        "size": 300,             # Size of the QR code (in pixels)
        "format": "png"          # Output format of the QR code image
    }

    try:
        # Send a GET request to the API
        response = requests.get(api_url, params=params)

        # Raise an exception if the request was unsuccessful
        response.raise_for_status()

        # Save the QR code image to the specified file
        with open(output_file, "wb") as file:
            file.write(response.content)

        print(f"QR code successfully generated and saved to {output_file}")

    except requests.exceptions.RequestException as e:
        # Handle any errors that occur during the API request
        print(f"An error occurred while generating the QR code: {e}")

